/* Palette: dark navy background, cream card, teal accent, coral highlight, dark text */
:root {
  --bg: #1a1c2c;
  --card: #f4f0e6;
  --accent: #2a9d8f;
  --accent-dark: #21867a;
  --highlight: #e76f51;
  --text: #2b2b2b;
  --muted: #6b6b6b;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  background-color: var(--bg);
  background-image: linear-gradient(45deg, #22243a 25%, transparent 25%),
                    linear-gradient(-45deg, #22243a 25%, transparent 25%),
                    linear-gradient(45deg, transparent 75%, #22243a 75%),
                    linear-gradient(-45deg, transparent 75%, #22243a 75%);
  background-size: 16px 16px;
  background-position: 0 0, 0 8px, 8px -8px, -8px 0;
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  font-family: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
  font-size: 16px;
  color: var(--text);
  padding: 16px;
}

.card {
  background: var(--card);
  border: 4px solid var(--accent);
  border-radius: 0;
  box-shadow: 8px 8px 0 var(--accent-dark);
  padding: 24px;
  width: 100%;
  max-width: 420px;
}

h1 {
  font-size: 28px;
  text-align: center;
  margin-bottom: 24px;
  color: var(--accent-dark);
  letter-spacing: 2px;
  text-transform: uppercase;
}

.field {
  margin-bottom: 20px;
  border: none;
}

label, legend {
  display: block;
  font-weight: 600;
  margin-bottom: 6px;
  font-size: 16px;
}

input[type="number"] {
  width: 100%;
  padding: 12px;
  font-size: 18px;
  font-family: inherit;
  border: 3px solid var(--accent);
  border-radius: 0;
  background: #fff;
  color: var(--text);
  transition: border-color 0.15s, box-shadow 0.15s;
}

input[type="number"]:focus {
  outline: none;
  border-color: var(--highlight);
  box-shadow: 0 0 0 3px rgba(231, 111, 81, 0.35);
}

.tip-buttons {
  display: flex;
  gap: 10px;
}

.tip-btn {
  flex: 1;
  padding: 12px 8px;
  font-size: 18px;
  font-weight: 700;
  font-family: inherit;
  background: #fff;
  color: var(--accent-dark);
  border: 3px solid var(--accent);
  border-radius: 0;
  cursor: pointer;
  transition: background 0.15s, color 0.15s, transform 0.1s, box-shadow 0.15s;
}

.tip-btn:hover {
  background: var(--accent);
  color: #fff;
}

.tip-btn:focus-visible {
  outline: none;
  box-shadow: 0 0 0 3px var(--highlight);
}

.tip-btn[aria-pressed="true"] {
  background: var(--accent);
  color: #fff;
  border-color: var(--accent-dark);
  box-shadow: inset 0 3px 0 rgba(0, 0, 0, 0.2);
  transform: translateY(2px);
}

.tip-btn:active {
  transform: translateY(2px);
  box-shadow: inset 0 3px 0 rgba(0, 0, 0, 0.2);
}

.results {
  margin-top: 24px;
  border-top: 3px dashed var(--accent);
  padding-top: 16px;
}

.result-row {
  display: flex;
  justify-content: space-between;
  align-items: baseline;
  padding: 10px 0;
  font-size: 18px;
}

.result-label {
  font-weight: 600;
  color: var(--muted);
}

.result-value {
  font-weight: 700;
  font-size: 22px;
  color: var(--accent-dark);
  font-variant-numeric: tabular-nums;
}

@media (max-width: 400px) {
  .card {
    padding: 16px;
  }
  h1 {
    font-size: 24px;
  }
  .tip-btn {
    padding: 10px 4px;
    font-size: 16px;
  }
}

(function () {
  'use strict';

  var billInput = document.getElementById('bill');
  var peopleInput = document.getElementById('people');
  var tipButtons = document.querySelectorAll('.tip-btn');
  var tipPerPersonEl = document.getElementById('tip-per-person');
  var totalPerPersonEl = document.getElementById('total-per-person');

  var tipPercent = 15; // default selected

  function formatCurrency(value) {
    return '$' + value.toFixed(2);
  }

  function calculate() {
    var bill = parseFloat(billInput.value);
    var people = parseInt(peopleInput.value, 10);

    if (isNaN(bill) || bill < 0) bill = 0;
    if (isNaN(people) || people < 1) people = 1;

    var tipAmount = bill * (tipPercent / 100);
    var tipPerPerson = tipAmount / people;
    var totalPerPerson = (bill + tipAmount) / people;

    tipPerPersonEl.textContent = formatCurrency(tipPerPerson);
    totalPerPersonEl.textContent = formatCurrency(totalPerPerson);
  }

  function selectTip(percent) {
    tipPercent = percent;
    tipButtons.forEach(function (btn) {
      var isSelected = parseInt(btn.getAttribute('data-tip'), 10) === percent;
      btn.setAttribute('aria-pressed', isSelected ? 'true' : 'false');
    });
    calculate();
  }

  tipButtons.forEach(function (btn) {
    btn.addEventListener('click', function () {
      selectTip(parseInt(btn.getAttribute('data-tip'), 10));
    });
  });

  billInput.addEventListener('input', calculate);
  peopleInput.addEventListener('input', calculate);

  // Initialize default selection
  selectTip(15);
})();
